    if expected is not None:assert score==expected
    works.append({'materialId':bodies[index]['id'],'workId':name,'wholeFourTaskSubmission':answers,'manualRubricDecisions':[{'step':i+1,'awarded':m,'maximum':6,'reason':r} for i,(m,r) in enumerate(zip(marks,reason))],'rawPoints':raw,'actualExistingCapApplied':cap,'finalPoints':score,'result':'PASS' if score>=15 else 'FAIL','claims':'Own fictional reviewer work, not learner evidence or human release'})
